// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        Reverter helper = new Reverter();
        vm.deal(address(c), amount);

        bool ok;
        try c.sendTo(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: sendTo either reverts, or it actually delivered `amount` wei
        // to the receiver. P (transfer) always reverts on the rejecting
        // helper, so ok is false. M (unchecked send) succeeds with ok=true
        // while the helper received nothing, breaking the rule.
        assertTrue(!ok || address(helper).balance == amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
